guard let logo = NSImage(contentsOf: logoURL) else {
  fputs("找不到 Logo：\(logoURL.path)\n", stderr)
  exit(1)
}

// 取 Logo 顶部中间像素作为压平底色（Logo 自带深色圆角背景）。
guard let tiff = logo.tiffRepresentation,
  let sourceRep = NSBitmapImageRep(data: tiff),
  let background = sourceRep.colorAt(x: sourceRep.pixelsWide / 2, y: 60)
else {
  fputs("无法读取 Logo 像素\n", stderr)
  exit(1)
}
let opaqueBackground = background.withAlphaComponent(1)

func writePNG(size: Int, to url: URL) throws {
  guard
    let rep = NSBitmapImageRep(
      bitmapDataPlanes: nil,
      pixelsWide: size,
      pixelsHigh: size,
      bitsPerSample: 8,
      samplesPerPixel: 4,
      hasAlpha: false,
      isPlanar: false,
      colorSpaceName: .deviceRGB,
      bytesPerRow: 0,
      bitsPerPixel: 0
    )
  else {
    throw NSError(domain: "assets", code: 1)
  }
  NSGraphicsContext.saveGraphicsState()
  NSGraphicsContext.current = NSGraphicsContext(bitmapImageRep: rep)
  NSGraphicsContext.current?.imageInterpolation = .high
  opaqueBackground.setFill()
  NSRect(x: 0, y: 0, width: size, height: size).fill()
  logo.draw(
    in: NSRect(x: 0, y: 0, width: size, height: size),
    from: NSRect(origin: .zero, size: logo.size),
    operation: .sourceOver,
    fraction: 1
  )
  NSGraphicsContext.restoreGraphicsState()
  guard let data = rep.representation(using: .png, properties: [:]) else {
    throw NSError(domain: "assets", code: 2)
  }
  try data.write(to: url)
}

func writeLaunchPNG(size: Int, to url: URL) throws {
