                        }
                    }
                    Spacer(Modifier.height(12.dp))
                }
            }
            if (submitting) {
                Spacer(Modifier.height(12.dp))
                Text("提交中…", fontSize = 20.sp, color = Color(0xFFB0B0B0))
            }
        } else {
            Text(
                text = if (result.correct) "回答正确" else "回答错误",
                fontSize = 40.sp,
                fontWeight = FontWeight.Bold,
                color = if (result.correct) Color(0xFF7CFF9B) else Color(0xFFFF7A7A),
            )
