package com.openquizgo.guard.domain

import com.openquizgo.guard.data.foreground.PlaybackSource
import com.openquizgo.guard.data.local.LocalSettingsStore
import com.openquizgo.guard.platform.GuardLog
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.delay
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.isActive
import kotlinx.coroutines.launch

enum class LocalGuardState {
    IDLE,
    WATCHING,
    QUIZ_REQUIRED,
    QUIZZING,
    GRANTED,
}

/**
 * 本地守护状态机（077）。
 *
 * 只统计媒体播放时间：累计满 [intervalSeconds] 秒进入 QUIZ_REQUIRED；
 * 答对后计时清零并回到观看态；答错由答题界面保持 QUIZZING，直到答对。
 */
class LocalGuardEngine(
    private val settings: LocalSettingsStore,
    private val playback: PlaybackSource,
    private val scope: CoroutineScope,
    val intervalSeconds: Long = DEFAULT_INTERVAL_SECONDS,
    private val tickMillis: Long = 1_000L,
    private val persistEveryTicks: Int = 10,
) {
    private val _state = MutableStateFlow(LocalGuardState.IDLE)
    val state: StateFlow<LocalGuardState> = _state.asStateFlow()

    private val _enabled = MutableStateFlow(true)
    val enabled: StateFlow<Boolean> = _enabled.asStateFlow()

    private val _elapsedSeconds = MutableStateFlow(0L)
    val elapsedSeconds: StateFlow<Long> = _elapsedSeconds.asStateFlow()

    private val _remainingSeconds = MutableStateFlow(intervalSeconds)
    val remainingSeconds: StateFlow<Long> = _remainingSeconds.asStateFlow()

    private val _lastQuestionId = MutableStateFlow<String?>(null)
    val lastQuestionId: StateFlow<String?> = _lastQuestionId.asStateFlow()

    @Volatile
    private var ready = false

    private var tickCount = 0
    private var lastSavedElapsed = -1L

    init {
        scope.launch { restore() }
        scope.launch { tickLoop() }
    }

    fun setEnabled(value: Boolean) {
        if (_enabled.value == value) return
        _enabled.value = value
        if (value) {
            _state.value = if (playback.mediaActive.value) {
                LocalGuardState.WATCHING
            } else {
                LocalGuardState.IDLE
            }
        } else {
            _elapsedSeconds.value = 0
            _remainingSeconds.value = intervalSeconds
            _state.value = LocalGuardState.IDLE
        }
        persist()
        GuardLog.i("local", "quiz enabled=$value")
    }

    fun onQuizStarted() {
        _state.value = LocalGuardState.QUIZZING
        GuardLog.i("local", "quiz started")
    }

    fun onQuizPassed(questionId: String) {
        rememberQuestion(questionId)
        _elapsedSeconds.value = 0
        _remainingSeconds.value = intervalSeconds
        _state.value = LocalGuardState.GRANTED
        persist()
        GuardLog.i("local", "quiz passed question=$questionId, timer reset")
    }

    fun onQuizCancelled() {
        _state.value = if (_enabled.value) {
            LocalGuardState.QUIZ_REQUIRED
        } else {
            LocalGuardState.IDLE
        }
    }

    /** 记住本轮的题目，下一轮优先换一题。 */
    fun rememberQuestion(questionId: String) {
        if (_lastQuestionId.value == questionId) return
        _lastQuestionId.value = questionId
        scope.launch { runCatching { settings.saveLastQuestionId(questionId) } }
    }

    private suspend fun restore() {
        val snapshot = runCatching { settings.snapshot() }.getOrElse { error ->
            GuardLog.e("local", "read settings failed", error)
            null
        }
        if (snapshot != null) {
            _enabled.value = snapshot.enabled
            _elapsedSeconds.value = snapshot.elapsedSeconds.coerceIn(0, intervalSeconds)
            _lastQuestionId.value = snapshot.lastQuestionId
        }
        _remainingSeconds.value = (intervalSeconds - _elapsedSeconds.value).coerceAtLeast(0)
        _state.value = when {
            !_enabled.value -> LocalGuardState.IDLE
            _elapsedSeconds.value >= intervalSeconds -> LocalGuardState.QUIZ_REQUIRED
            else -> LocalGuardState.IDLE
        }
        ready = true
        GuardLog.i(
            "local",
            "restored enabled=${_enabled.value} elapsed=${_elapsedSeconds.value}s " +
                "state=${_state.value}",
        )
    }

    private suspend fun tickLoop() {
        while (scope.isActive) {
            delay(tickMillis)
            if (!ready) continue

            if (!_enabled.value) {
                if (_state.value != LocalGuardState.IDLE) {
                    _state.value = LocalGuardState.IDLE
                }
                continue
            }

            when (_state.value) {
                LocalGuardState.QUIZ_REQUIRED,
                LocalGuardState.QUIZZING,
                -> Unit

                else -> {
                    if (playback.mediaActive.value) {
                        if (_state.value == LocalGuardState.IDLE ||
                            _state.value == LocalGuardState.GRANTED
                        ) {
                            _state.value = LocalGuardState.WATCHING
                        }
                        val next = (_elapsedSeconds.value + 1).coerceAtMost(intervalSeconds)
                        _elapsedSeconds.value = next
                        if (next >= intervalSeconds) {
                            _state.value = LocalGuardState.QUIZ_REQUIRED
                            GuardLog.i("local", "quiz due after ${next}s")
                            persist()
                        }
                    } else if (_state.value == LocalGuardState.WATCHING ||
                        _state.value == LocalGuardState.GRANTED
                    ) {
                        _state.value = LocalGuardState.IDLE
                    }
                }
            }

            _remainingSeconds.value = (intervalSeconds - _elapsedSeconds.value).coerceAtLeast(0)
            tickCount += 1
            if (persistEveryTicks > 0 && tickCount % persistEveryTicks == 0) {
                persist()
            }
        }
    }

    private fun persist() {
        val enabled = _enabled.value
        val elapsed = _elapsedSeconds.value
        if (lastSavedElapsed == elapsed && lastSavedElapsed >= 0) return
        lastSavedElapsed = elapsed
        scope.launch {
            runCatching {
                settings.saveEnabled(enabled)
                settings.saveElapsedSeconds(elapsed)
            }.onFailure { GuardLog.w("local", "persist failed: ${it.message}") }
        }
    }

    companion object {
        const val DEFAULT_INTERVAL_SECONDS = 15L * 60L
    }
}

package com.openquizgo.guard.platform

import android.accessibilityservice.AccessibilityService
import android.accessibilityservice.AccessibilityServiceInfo
import android.content.Intent
import android.view.accessibility.AccessibilityEvent
import com.openquizgo.guard.ui.QuizActivity
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow

object ForegroundTracker {
    private val _packageName = MutableStateFlow<String?>(null)
    val packageName: StateFlow<String?> = _packageName.asStateFlow()

    fun update(pkg: CharSequence?) {
        val value = pkg?.toString()?.trim().orEmpty()
        if (value.isNotEmpty() && value != _packageName.value) {
            _packageName.value = value
        }
    }
}

/**
 * 无障碍服务：记录前台应用，并提供「从系统绑定服务拉起 Activity」的可靠通道。
 *
 * Android 10+ 对后台启动 Activity 有严格限制；通过无障碍服务启动答题界面
 * 是电视端到点自动弹题的关键路径。
 */
class GuardAccessibilityService : AccessibilityService() {

    override fun onServiceConnected() {
        super.onServiceConnected()
        instance = this
        getServiceInfo()?.let { info ->
            info.flags = info.flags or AccessibilityServiceInfo.FLAG_INCLUDE_NOT_IMPORTANT_VIEWS
            setServiceInfo(info)
        }
        GuardLog.i("accessibility", "connected")
    }

    override fun onAccessibilityEvent(event: AccessibilityEvent?) {
        if (event?.eventType != AccessibilityEvent.TYPE_WINDOW_STATE_CHANGED) return
        val pkg = event.packageName ?: return
        ForegroundTracker.update(pkg)
        GuardLog.i("foreground=$pkg cls=${event.className}")
    }

    override fun onInterrupt() {
        GuardLog.w("accessibility", "interrupted")
    }

    private fun launchQuiz() {
        val intent = Intent(this, QuizActivity::class.java)
            .addFlags(Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TOP)
        runCatching { startActivity(intent) }
            .onSuccess { GuardLog.i("accessibility", "quiz activity launched") }
            .onFailure { GuardLog.e("accessibility", "quiz launch failed", it) }
    }

    override fun onDestroy() {
        instance = null
        super.onDestroy()
    }

    companion object {
        @Volatile
        private var instance: GuardAccessibilityService? = null

        fun launchQuizActivity(): Boolean {
            val service = instance ?: return false
            service.launchQuiz()
            return true
        }

        fun isConnected(): Boolean = instance != null
    }
}

package com.openquizgo.guard.platform

import android.app.Notification
import android.app.NotificationChannel
import android.app.NotificationManager
import android.app.PendingIntent
import android.app.Service
import android.content.Context
import android.content.Intent
import android.os.Build
import android.os.Handler
import android.os.IBinder
import android.os.Looper
import android.widget.Toast
import com.openquizgo.guard.GuardApplication
import com.openquizgo.guard.domain.LocalGuardState
import com.openquizgo.guard.ui.MainActivity
import com.openquizgo.guard.ui.QuizActivity
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.Job
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.delay
import kotlinx.coroutines.flow.combine
import kotlinx.coroutines.isActive
import kotlinx.coroutines.launch

/**
 * 前台守护服务（本地模式）。
 *
 * 观察本地状态机：累计播放满 15 分钟进入 QUIZ_REQUIRED 后拉起答题界面；
 * 看门狗在答题界面被切走/关闭时重新拉起，确保「答对前不能继续看」。
 */
class GuardService : Service() {

    private val scope = CoroutineScope(SupervisorJob() + Dispatchers.Default)
    private val mainHandler = Handler(Looper.getMainLooper())
    private var stateJob: Job? = null
    private var watchdogJob: Job? = null
    private var engine: com.openquizgo.guard.domain.LocalGuardEngine? = null
    private var lastQuizLaunchAt = 0L
    private var quizNotified = false

    override fun onCreate() {
        super.onCreate()
        GuardLog.i("service", "local guard service created")
        createChannel()
        startForeground(NOTIFICATION_ID, buildNotification("启动中"))
        engine = (application as GuardApplication).container.guardEngine
        stateJob = scope.launch {
            combine(engine!!.enabled, engine!!.state) { enabled, state ->
                enabled to state
            }.collect { (enabled, state) ->
                updateNotification(label(enabled, state))
                when (state) {
                    LocalGuardState.QUIZ_REQUIRED -> {
                        if (!quizNotified) {
                            quizNotified = true
                            toast("答题时间到，答对后继续观看")
                        }
                        launchQuiz()
                    }
                    LocalGuardState.QUIZZING -> Unit
                    else -> {
                        quizNotified = false
                    }
                }
            }
        }
        watchdogJob = scope.launch {
            while (isActive) {
                delay(WATCHDOG_INTERVAL_MS)
                watchdogTick()
            }
        }
    }

    private fun watchdogTick() {
        val current = engine?.state?.value ?: return
        if (current != LocalGuardState.QUIZ_REQUIRED &&
            current != LocalGuardState.QUIZZING
        ) {
            return
        }
        if (QuizActivity.isShowing) return
        if (System.currentTimeMillis() - lastQuizLaunchAt < RELAUNCH_GAP_MS) return
        GuardLog.w("watchdog", "quiz activity missing, relaunch")
        launchQuiz()
    }

    private fun launchQuiz() {
        lastQuizLaunchAt = System.currentTimeMillis()
        if (GuardAccessibilityService.launchQuizActivity()) {
            GuardLog.i("service", "quiz launched via accessibility")
            return
        }
        GuardLog.w("service", "accessibility unavailable, fallback startActivity")
        val intent = Intent(this, QuizActivity::class.java)
            .addFlags(Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TOP)
        runCatching { startActivity(intent) }
            .onFailure {
                GuardLog.e("service", "quiz launch failed", it)
                toast("请开启无障碍服务，否则无法自动弹出答题")
            }
    }

    override fun onStartCommand(intent: Intent?, flags: Int, startId: Int): Int {
        return START_STICKY
    }

    override fun onDestroy() {
        stateJob?.cancel()
        watchdogJob?.cancel()
        super.onDestroy()
    }

    override fun onBind(intent: Intent?): IBinder? = null

    private fun toast(message: String) {
        mainHandler.post {
            Toast.makeText(this, message, Toast.LENGTH_LONG).show()
        }
    }

    private fun createChannel() {
        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.O) return
        val manager = getSystemService(NOTIFICATION_SERVICE) as NotificationManager
        val channel = NotificationChannel(
            CHANNEL_ID,
            "定时答题",
            NotificationManager.IMPORTANCE_LOW,
        )
        manager.createNotificationChannel(channel)
    }

    private fun buildNotification(text: String): Notification {
        val pending = PendingIntent.getActivity(
            this,
            0,
            Intent(this, MainActivity::class.java),
            PendingIntent.FLAG_IMMUTABLE,
        )
        val builder = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            Notification.Builder(this, CHANNEL_ID)
        } else {
            Notification.Builder(this)
        }
        return builder
            .setSmallIcon(android.R.drawable.ic_lock_idle_alarm)
            .setContentTitle("电视时间管家 · 定时答题")
            .setContentText(text)
            .setContentIntent(pending)
            .setOngoing(true)
            .build()
    }

    private fun updateNotification(text: String) {
        val manager = getSystemService(NOTIFICATION_SERVICE) as NotificationManager
        manager.notify(NOTIFICATION_ID, buildNotification(text))
    }

    private fun label(enabled: Boolean, state: LocalGuardState): String {
        if (!enabled) return "已关闭，不会弹出答题"
        return when (state) {
            LocalGuardState.IDLE -> "已开启 · 等待视频播放"
            LocalGuardState.WATCHING -> "已开启 · 正在累计观看时间"
            LocalGuardState.QUIZ_REQUIRED -> "答题时间到"
            LocalGuardState.QUIZZING -> "答题中，答对后继续"
            LocalGuardState.GRANTED -> "回答正确，继续观看"
        }
    }

    companion object {
        private const val CHANNEL_ID = "local_quiz"
        private const val NOTIFICATION_ID = 1001
        private const val WATCHDOG_INTERVAL_MS = 2_000L
        private const val RELAUNCH_GAP_MS = 3_000L

        fun start(context: Context) {
            val intent = Intent(context, GuardService::class.java)
            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
                context.startForegroundService(intent)
            } else {
                context.startService(intent)
            }
        }
    }
}

package com.openquizgo.guard.ui

import androidx.lifecycle.ViewModel
import androidx.lifecycle.ViewModelProvider
import com.openquizgo.guard.di.AppContainer
import com.openquizgo.guard.domain.LocalGuardEngine
import com.openquizgo.guard.domain.LocalGuardState
import kotlinx.coroutines.flow.StateFlow

class LocalViewModel(
    private val engine: LocalGuardEngine,
    val questionCount: Int,
) : ViewModel() {

    val enabled: StateFlow<Boolean> = engine.enabled
    val state: StateFlow<LocalGuardState> = engine.state
    val elapsedSeconds: StateFlow<Long> = engine.elapsedSeconds
    val remainingSeconds: StateFlow<Long> = engine.remainingSeconds

    fun toggleQuiz() {
        engine.setEnabled(!enabled.value)
    }

    class Factory(private val container: AppContainer) : ViewModelProvider.Factory {
        @Suppress("UNCHECKED_CAST")
        override fun <T : ViewModel> create(modelClass: Class<T>): T {
            return LocalViewModel(
                engine = container.guardEngine,
                questionCount = container.questionBank.size,
            ) as T
        }
    }
}

