            Spacer(Modifier.height(16.dp))
            Text(
                "请安装包含题库的版本，或先关闭定时答题",
                fontSize = 22.sp,
                color = Color(0xFFB0B0B0),
            )
            Spacer(Modifier.height(32.dp))
            Button(onClick = onDisable) { Text("关闭定时答题", fontSize = 24.sp) }
        }
        return
    }

    Column(
        modifier = Modifier
            .fillMaxSize()
            .background(Color(0xFF0B0B0B))
            .padding(horizontal = 72.dp, vertical = 48.dp),
        verticalArrangement = Arrangement.Center,
        horizontalAlignment = Alignment.CenterHorizontally,
    ) {
        Text(
            text = "答题时间到",
            fontSize = 26.sp,
            color = Color(0xFFFFC107),
        )
        Spacer(Modifier.height(10.dp))
        Text(
            text = "答对后继续观看",
            fontSize = 18.sp,
            color = Color(0xFF909090),
        )
        Spacer(Modifier.height(28.dp))
        Text(
            text = question.stem,
            fontSize = 42.sp,
            fontWeight = FontWeight.Bold,
            color = Color.White,
        )
        Spacer(Modifier.height(32.dp))

        if (!solved) {
            question.options.forEachIndexed { index, option ->
                val wrong = option.id == wrongOptionId
                Button(
                    onClick = { onSelect(option.id) },
                    modifier = if (index == 0) {
                        Modifier.focusRequester(firstOptionFocus)
                    } else {
                        Modifier
                    },
                ) {
                    Text(
                        text = "${option.id.uppercase()}. ${option.text}",
                        fontSize = 26.sp,
                        color = if (wrong) Color(0xFFFF7A7A) else Color.Unspecified,
                    )
                }
                Spacer(Modifier.height(10.dp))
            }
            if (wrongOptionId != null) {
                Spacer(Modifier.height(6.dp))
                Text(
                    text = if (attempts >= 2) "再读一遍题目，答对才能继续" else "答错了，再试一次",
                    fontSize = 22.sp,
                    color = Color(0xFFFF7A7A),
                )
            }
        } else {
            Text(
                text = "回答正确！",
                fontSize = 40.sp,
                fontWeight = FontWeight.Bold,
                color = Color(0xFF7CFF9B),
            )
            question.explain.takeIf { it.isNotBlank() }?.let {
                Spacer(Modifier.height(12.dp))
                Text(text = it, fontSize = 22.sp, color = Color(0xFFD0D0D0))
            }
            Spacer(Modifier.height(28.dp))
            Button(onClick = onContinue) {
                Text("继续观看", fontSize = 26.sp)
            }
        }
    }
}

